practice_labels = {"My parcel is late.": "delivery", "I forgot my password.": "account",
                   "Where is my delivery?": "delivery"}
replies = {"delivery": "Please share the tracking number.",
           "account": "Please share the login error message."}

def classify(state):
    label = client.ask("Return only delivery or account for: " + state["message"],
        practice=practice_labels.get(state["message"], "unknown")).strip().lower()
    if label not in replies:
        raise ValueError("Unknown category; ask a human")
    return {"category": label}

def write_reply(state):
    return {"reply": replies[state["category"]]}

def plain_python(message):
    state = {"message": message}
    state.update(classify(state))
    state.update(write_reply(state))
    return state

plain_result = plain_python("My parcel is late.")
print(plain_result)
assert plain_result["reply"].strip()
